#r "nuget: Markout, 0.22.0"

using System.Reflection;
using Markout.Formatting;

var asm = AppDomain.CurrentDomain.GetAssemblies().FirstOrDefault(a => a.GetName().Name == "Markout");
var types = asm.GetTypes()
    .Where(t => !t.Name.StartsWith("<") && t.Name.Contains("Formatter"))
    .OrderBy(t => t.FullName)
    .ToList();

Console.WriteLine("Formatter types:");
foreach (var t in types)
{
    Console.WriteLine($"\n{t.FullName}");
    var methods = t.GetMethods(BindingFlags.Public | BindingFlags.Static)
        .Where(m => !m.Name.StartsWith("get_") && !m.Name.StartsWith("set_") && !m.IsSpecialName)
        .ToList();
    if (methods.Any())
    {
        Console.WriteLine("  Static methods:");
        foreach (var m in methods.Take(3))
        {
            Console.WriteLine($"    {m.Name}({string.Join(", ", m.GetParameters().Select(p => p.ParameterType.Name))})");
        }
    }
}

// Also look for any Create/New methods
Console.WriteLine("\n\nLooking for factory methods:");
var factoryTypes = asm.GetTypes()
    .Where(t => t.GetMethods(BindingFlags.Public | BindingFlags.Static).Any(m => m.Name == "Create" || m.Name == "New"))
    .ToList();

foreach (var t in factoryTypes.Take(10))
{
    Console.WriteLine($"\n{t.Name}");
    var methods = t.GetMethods(BindingFlags.Public | BindingFlags.Static)
        .Where(m => m.Name == "Create" || m.Name == "New")
        .ToList();
    foreach (var m in methods.Take(2))
    {
        Console.WriteLine($"  {m.Name}");
    }
}
EOF
