{
    var parms = string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
    Console.WriteLine($"  {m.Name}({parms}) -> {m.ReturnType.Name}");
}

Console.WriteLine("\n\nPlainTextFormatter:");
var ptMethods = ptFmt.GetMethods(BindingFlags.Public | BindingFlags.Static | BindingFlags.Instance)
    .Where(m => !m.IsSpecialName)
    .ToList();
foreach (var m in ptMethods.Take(10))
{
    var parms = string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
    Console.WriteLine($"  {m.Name}({parms}) -> {m.ReturnType.Name}");
}

Console.WriteLine("\n\nMarkoutWriter:");
var writerType = asm.GetType("Markout.MarkoutWriter");
var writerMethods = writerType.GetMethods(BindingFlags.Public | BindingFlags.Static)
    .Where(m => m.Name == "Create")
    .ToList();
foreach (var m in writerMethods)
{
    var parms = string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
